mapper.select:
select d.dept_id as deptId, d.parent_id as parentId, d.ancestors, d.dept_name as deptName, d.order_num as orderNum, d.leader, d.phone, d.email, d.status, d.create_time as createTime from sys_dept d where d.del_flag = '0'
AND dept_id = #{deptId}
AND parent_id = #{parentId}
AND dept_name like concat('%', #{deptName}, '%')
AND status = #{status}
${params.dataScopeQuery} order by d.parent_id, d.order_num

select d.dept_id as deptId from sys_dept d left join sys_role_dept rd on d.dept_id = rd.dept_id where rd.role_id = #{roleId}
and d.dept_id not in (select d.parent_id from sys_dept d inner join sys_role_dept rd on d.dept_id = rd.dept_id and rd.role_id = #{roleId})
order by d.parent_id, d.order_num

